<script setup lang="ts">
import type {Company,CompanyInput} from '../types';
import { reactive } from 'vue';
const props=defineProps<{company:Company|null;busy:boolean;error:string}>();
const emit=defineEmits<{save:[input:CompanyInput];cancel:[]}>();
const draft=reactive<CompanyInput>(props.company?{code:props.company.code,name:props.company.name,provider:props.company.provider,status:props.company.status,contactName:props.company.contactName,contactPhone:props.company.contactPhone,sortOrder:props.company.sortOrder,remark:props.company.remark,version:props.company.version}:{code:'',name:'',provider:'MANUAL',status:'disabled',contactName:'',contactPhone:'',sortOrder:0,remark:'',version:0});
</script>
<template><form class="space-y-5" data-testid="company-form" @submit.prevent="emit('save',{...draft})"><p v-if="error" role="alert" class="rounded bg-rose-50 p-3 text-sm text-rose-700">{{ error }}</p><fieldset :disabled="busy" class="grid grid-cols-1 gap-5 md:grid-cols-2"><label>公司名称 <span class="text-rose-500">*</span><input v-model.trim="draft.name" name="company-name" required maxlength="100" class="control" placeholder="填写合作物流公司名称"></label><label>内部编码 <span class="text-rose-500">*</span><input v-model.trim="draft.code" name="company-code" required maxlength="50" class="control" placeholder="唯一内部编码"></label><label>接口类型<select v-model="draft.provider" class="control"><option value="MANUAL">未接入 / 线下下单</option><option value="ANE">安能 ANE</option></select></label><label>合作状态<select v-model="draft.status" class="control"><option value="disabled">停用</option><option value="enabled">启用合作</option></select></label><label>联系人<input v-model.trim="draft.contactName" class="control" maxlength="100"></label><label>联系电话<input v-model.trim="draft.contactPhone" class="control" maxlength="50" type="tel"></label><label>排序<input v-model.number="draft.sortOrder" class="control" type="number" min="0" step="1"></label><label class="md:col-span-2">备注<textarea v-model="draft.remark" class="control" rows="3" maxlength="1000" /></label></fieldset><p class="text-xs text-slate-500">合作启用后仍需配置合同费率才能估价；接口下单能力取决于已接入的适配器与完整账号配置。</p><div class="flex justify-end gap-3"><button type="button" :disabled="busy" class="rounded-lg border px-5 py-2 text-sm" @click="emit('cancel')">返回列表</button><button :disabled="busy" class="rounded-lg bg-indigo-500 px-5 py-2 text-sm font-semibold text-white">{{ busy?'保存中…':'保存公司资料' }}</button></div></form></template>
<style scoped>label{@apply block text-sm text-slate-600;}.control{@apply mt-2 block w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-800 outline-none focus:border-indigo-400;}button:disabled{@apply opacity-40;}</style>
